<?php if ( is_active_sidebar( 'sidebar-1' ) ) : ?><aside id="secondary" class="widget-area shop-sidebar"><?php dynamic_sidebar( 'sidebar-1' ); ?></aside><?php else : ?><aside id="secondary" class="widget-area shop-sidebar"><div class="filter-heading"><h2><?php esc_html_e( 'Filter products', 'souqify' ); ?></h2><button type="button" class="clear-filters"><?php esc_html_e( 'Clear all', 'souqify' ); ?></button></div><div class="filter-group"><h3><?php esc_html_e( 'Search within category', 'souqify' ); ?></h3><input type="search" class="category-search" placeholder="<?php esc_attr_e( 'Search products…', 'souqify' ); ?>"></div><div class="filter-group"><h3><?php esc_html_e( 'Categories', 'souqify' ); ?></h3><?php if ( function_exists( 'get_terms' ) ) { $terms = get_terms( array( 'taxonomy' => 'product_cat', 'hide_empty' => true, 'parent' => 0 ) ); if ( ! is_wp_error( $terms ) ) { foreach ( $terms as $term ) { echo '<label class="filter-check"><input type="checkbox" name="product_cat[]" value="' . esc_attr( $term->slug ) . '"><span>' . esc_html( $term->name ) . '</span><small>' . esc_html( $term->count ) . '</small></label>'; } } } ?></div><div class="filter-group"><h3><?php esc_html_e( 'Availability', 'souqify' ); ?></h3><label class="switch-row"><input type="checkbox" name="in_stock"><span class="switch"></span><?php esc_html_e( 'In stock only', 'souqify' ); ?></label></div></aside><?php endif; ?>
